import { WorkspaceShell, WorkspacePanels } from "@/components/design-for-ai/layout-workspace-shell";

const [view, setView] = useState("overview");

<WorkspaceShell
  brand="Northstar"
  eyebrow="Studio workspace"
  title="Overview"
  links={[
    { id: "overview", label: "Overview", href: "#overview" },
    { id: "projects", label: "Projects", href: "#projects", badge: 5 },
  ]}
  activeId={view}
  onNavigate={setView}
  className="h-[820px]"
>
  <WorkspacePanels fill activeId={view} panels={[
    { id: "overview", content: <section id="overview" role="tabpanel">…</section> },
    { id: "projects", content: <section id="projects" role="tabpanel">…</section> },
  ]} />
</WorkspaceShell>

// Children can use the shell's tokens: var(--ws-surface), var(--ws-line), var(--ws-ink), var(--ws-muted).
